    ar: 'اعتبارًا من الليلة التالية لا يفصل التدقيق الليلي أي فطور من سعر الغرفة، لا فطور السعر ولا فطور المنشأة.',
    pt: 'A partir da noite seguinte, a auditoria noturna não separa pequeno-almoço do preço do quarto, nem o da tarifa nem o do estabelecimento.',
    fi: 'Seuraavasta yöstä alkaen yöajo ei erota aamiaista huonehinnasta, ei hinnan eikä talon aamiaista.',
    is: 'Frá næstu nótt tekur næturuppgjörið engan morgunverð út úr herbergisverðinu, hvorki verðsins né hússins.',
