    ro: 'Micșorați ca să încapă toate camerele pe ecran. Dublu clic: implicit.',
    bg: 'Намалете, за да се съберат всички стаи на екрана. Двоен клик: по подразбиране.',
    hr: 'Smanjite kako bi sve sobe stale na zaslon. Dvostruki klik: zadano.',
    sr: 'Smanjite da bi sve sobe stale na ekran. Dvostruki klik: podrazumevano.',
    mk: 'Намалете за сите соби да се соберат на екранот. Двоен клик: стандардно.',
    sq: 'Zvogëlojeni që të gjitha dhomat të nxënë në ekran. Klikim i dyfishtë: standard.',
