    fr: 'Attention : la chambre {raum} a de la place pour {platz}, mais {bedarf} places ont été réservées. La réservation n’y tient pas entièrement.',
    it: 'Attenzione: {raum} ha posto per {platz}, ma sono stati prenotati {bedarf} posti. La prenotazione non ci sta interamente.',
    es: 'Atención: {raum} tiene capacidad para {platz} y se han reservado {bedarf} plazas. La reserva no cabe ahí por completo.',
    ru: 'Внимание: номер {raum} вмещает {platz}, а забронировано мест: {bedarf}. Бронирование туда целиком не помещается.',
    uk: 'Увага: номер {raum} має місця для {platz}, а заброньовано місць: {bedarf}. Бронювання там повністю не поміщається.',
    zh: '注意：{raum} 可住 {platz} 人，但预订了 {bedarf} 个床位。该预订无法完全安排在此。',
    ko: '주의: {raum}의 수용 인원은 {platz}명인데 {bedarf}명이 예약되었습니다. 예약이 이 객실에 모두 들어가지 않습니다.',
    ar: 'تنبيه: الغرفة {raum} تتسع لـ {platz}، والمحجوز {bedarf} أماكن. الحجز لا يتسع فيها بالكامل.',
    pt: 'Atenção: {raum} tem espaço para {platz}, estão reservados {bedarf} lugares. A reserva não cabe totalmente aí.',
    fi: 'Huomio: huoneessa {raum} on tilaa {platz} henkilölle, mutta varattuja paikkoja on {bedarf}. Varaus ei mahdu sinne kokonaan.',
    is: 'Athugið: herbergi {raum} rúmar {platz}, en bókuð eru {bedarf} pláss. Bókunin passar þar ekki að fullu.',
    sk: 'Pozor: izba {raum} má miesto pre {platz}, rezervovaných je {bedarf} miest. Rezervácia sa tam úplne nezmestí.',
    sl: 'Pozor: soba {raum} ima prostor za {platz}, rezerviranih pa je {bedarf} mest. Rezervacija tja ne paše v celoti.',
    hu: 'Figyelem: a(z) {raum} szoba {platz} főnek ad helyet, a foglalás {bedarf} főre szól. A foglalás nem fér el ott teljesen.',
    ro: 'Atenție: {raum} are loc pentru {platz}, dar sunt rezervate {bedarf} locuri. Rezervarea nu încape complet acolo.',
    bg: 'Внимание: {raum} предлага място за {platz}, резервирани са {bedarf} места. Резервацията не се побира изцяло там.',
    hr: 'Pozor: {raum} ima mjesta za {platz}, a rezervirano je mjesta: {bedarf}. Rezervacija ondje ne stane u potpunosti.',
