    sq: 'Kujdes: {raum} ka vend për {platz}, por janë rezervuar {bedarf} vende. Prenotimi nuk nxë plotësisht aty.',
    el: 'Προσοχή: το {raum} έχει χώρο για {platz}, έχουν κρατηθεί {bedarf} θέσεις. Η κράτηση δεν χωρά πλήρως εκεί.',
