    sq: 'Pas check-in mysafiri mbetet. Emrin e korrigjon profili i mysafirit.',
    el: 'Μετά το check-in ο επισκέπτης παραμένει. Το όνομα διορθώνεται στο προφίλ επισκέπτη.',
