    sr: 'Premeštanja se odmah čuvaju, bez pitanja. Ctrl+Z poništava poslednje.',
    mk: 'Поместувањата се зачувуваат веднаш, без прашање. Ctrl+Z го поништува последното.',
    sq: 'Zhvendosjet ruhen menjëherë, pa pyetur. Ctrl+Z zhbën të fundit.',
    el: 'Οι μετακινήσεις αποθηκεύονται αμέσως, χωρίς ερώτηση. Το Ctrl+Z αναιρεί την τελευταία.',
