  'kontext.checkOutConfirm': {
    de: 'Gast jetzt auschecken? Reist er vor dem gebuchten Tag ab, endet der Aufenthalt heute.',
    en: 'Check the guest out now? If they leave before the booked day, the stay ends today.',
    tr: 'Misafir şimdi çıkış yapsın mı? Rezerve edilen günden önce ayrılırsa konaklama bugün sona erer.',
    nl: 'Gast nu uitchecken? Vertrekt de gast vóór de geboekte dag, dan eindigt het verblijf vandaag.',
    da: 'Tjek gæsten ud nu? Rejser gæsten før den bookede dag, slutter opholdet i dag.',
    sv: 'Checka ut gästen nu? Reser gästen före det bokade datumet slutar vistelsen idag.',
    nb: 'Sjekke ut gjesten nå? Reiser gjesten før den bookede dagen, slutter oppholdet i dag.',
    pl: 'Wymeldować gościa teraz? Jeśli wyjeżdża przed zarezerwowanym dniem, pobyt kończy się dziś.',
    cs: 'Provést check-out hosta nyní? Odjíždí-li před rezervovaným dnem, pobyt končí dnes.',
    fr: 'Effectuer le check-out du client maintenant ? S’il part avant le jour réservé, le séjour se termine aujourd’hui.',
    it: 'Effettuare ora il check-out dell’ospite? Se parte prima del giorno prenotato, il soggiorno termina oggi.',
    es: '¿Hacer ahora el check-out del huésped? Si se va antes del día reservado, la estancia termina hoy.',
    ru: 'Выселить гостя сейчас? Если он уезжает раньше забронированного дня, проживание заканчивается сегодня.',
    uk: 'Виписати гостя зараз? Якщо він виїжджає раніше заброньованого дня, проживання закінчується сьогодні.',
    zh: '现在为宾客办理退房？如果早于预订日期离店，住宿将于今天结束。',
    ko: '지금 게스트를 체크아웃하시겠습니까? 예약일보다 일찍 떠나면 숙박은 오늘로 종료됩니다.',
    ar: 'تسجيل مغادرة النزيل الآن؟ إذا غادر قبل اليوم المحجوز، تنتهي الإقامة اليوم.',
    pt: 'Fazer agora o check-out do hóspede? Se partir antes do dia reservado, a estadia termina hoje.',
    fi: 'Kirjataanko vieras ulos nyt? Jos hän lähtee ennen varattua päivää, oleskelu päättyy tänään.',
    is: 'Útrita gestinn núna? Ef hann fer fyrir bókaðan dag lýkur dvölinni í dag.',
    sk: 'Odhlásiť hosťa teraz? Ak odchádza pred rezervovaným dňom, pobyt sa skončí dnes.',
    sl: 'Odjaviti gosta zdaj? Če odide pred rezerviranim dnem, se bivanje konča danes.',
    hu: 'Most kijelentkezteti a vendéget? Ha a foglalt nap előtt utazik el, a tartózkodás ma véget ér.',
    ro: 'Faceți acum check-out oaspetelui? Dacă pleacă înainte de ziua rezervată, sejurul se încheie azi.',
    bg: 'Да се освободи ли гостът сега? Ако заминава преди резервирания ден, престоят приключва днес.',
    hr: 'Odjaviti gosta sada? Ako odlazi prije rezerviranog dana, boravak završava danas.',
    sr: 'Odjaviti gosta sada? Ako odlazi pre rezervisanog dana, boravak se završava danas.',
    mk: 'Да се направи check-out на гостинот сега? Ако заминува пред резервираниот ден, престојот завршува денес.',
    sq: 'Të bëhet check-out i mysafirit tani? Nëse largohet para ditës së rezervuar, qëndrimi përfundon sot.',
    el: 'Check-out του επισκέπτη τώρα; Αν αναχωρεί πριν από την κρατημένη ημέρα, η διαμονή λήγει σήμερα.',
    lt: 'Išregistruoti svečią dabar? Jei jis išvyksta anksčiau nei užsakyta diena, viešnagė baigiasi šiandien.',
    lv: 'Izrakstīt viesi tagad? Ja viņš izbrauc pirms rezervētās dienas, uzturēšanās beidzas šodien.',
    et: 'Registreerida külaline kohe välja? Kui ta lahkub enne broneeritud päeva, lõpeb viibimine täna.' },
