    ko: '현황표의 막대에 표시되며, 함께 생성되는 유지보수 요청의 제목이 됩니다.',
    ar: 'يظهر على الشريط في المخطط، وهو عنوان بلاغ الصيانة الذي يُنشأ معه.',
    pt: 'Aparece no bloqueio no plano e é o título do pedido de manutenção criado com ele.',
