    hr: 'Prikazuje se na traci u planu i naslov je prijave kvara koja pritom nastaje.',
    sr: 'Prikazuje se na traci u planu i naslov je prijave kvara koja se pri tom kreira.',
    mk: 'Стои на лентата во планот и е наслов на пријавата за одржување што се создава.',
