  'group.mergeHint': {
    de: 'Für eine Gruppe, die in zwei Buchungen steht. Alle Zimmer der gewählten Buchung kommen in diese; Zeitraum, Zimmer, Preise und Gäste bleiben.',
    en: 'For a group split across two bookings. All rooms of the chosen booking move into this one; dates, rooms, prices and guests stay.',
    tr: 'İki rezervasyona bölünmüş bir grup için. Seçilen rezervasyonun tüm odaları buna taşınır; tarihler, odalar, fiyatlar ve misafirler aynı kalır.',
    nl: 'Voor een groep die in twee boekingen staat. Alle kamers van de gekozen boeking komen in deze; data, kamers, prijzen en gasten blijven.',
    da: 'Til en gruppe, der står i to bookinger. Alle værelser fra den valgte booking flyttes hertil; datoer, værelser, priser og gæster bliver.',
    sv: 'För en grupp som står i två bokningar. Alla rum i den valda bokningen flyttas hit; datum, rum, priser och gäster står kvar.',
    nb: 'For en gruppe som står i to bestillinger. Alle rom i den valgte bestillingen flyttes hit; datoer, rom, priser og gjester blir.',
    pl: 'Dla grupy rozdzielonej na dwie rezerwacje. Wszystkie pokoje wybranej rezerwacji trafią do tej; terminy, pokoje, ceny i goście pozostają.',
    cs: 'Pro skupinu rozdělenou do dvou rezervací. Všechny pokoje vybrané rezervace přejdou do této; termíny, pokoje, ceny a hosté zůstanou.',
    fr: 'Pour un groupe réparti sur deux réservations. Toutes les chambres de la réservation choisie rejoignent celle-ci ; dates, chambres, prix et clients restent.',
    it: 'Per un gruppo diviso in due prenotazioni. Tutte le camere della prenotazione scelta passano in questa; date, camere, prezzi e ospiti restano.',
    es: 'Para un grupo repartido en dos reservas. Todas las habitaciones de la reserva elegida pasan a esta; fechas, habitaciones, precios y huéspedes se mantienen.',
    ru: 'Для группы, разделённой на два бронирования. Все номера выбранного бронирования переходят в это; даты, номера, цены и гости остаются.',
    uk: 'Для групи, розділеної на два бронювання. Усі номери вибраного бронювання переходять до цього; дати, номери, ціни й гості лишаються.',
    zh: '适用于被拆成两个预订的团体。所选预订的所有房间将并入此预订；日期、房间、价格和宾客保持不变。',
    ko: '두 예약으로 나뉜 그룹용입니다. 선택한 예약의 모든 객실이 이 예약으로 옮겨지며, 날짜·객실·요금·게스트는 그대로입니다.',
    ar: 'لمجموعة موزعة على حجزين. تنتقل كل غرف الحجز المختار إلى هذا الحجز؛ وتبقى التواريخ والغرف والأسعار والنزلاء كما هي.',
    pt: 'Para um grupo dividido em duas reservas. Todos os quartos da reserva escolhida passam para esta; datas, quartos, preços e hóspedes mantêm-se.',
    fi: 'Kahteen varaukseen jakautuneelle ryhmälle. Valitun varauksen kaikki huoneet siirtyvät tähän; päivät, huoneet, hinnat ja vieraat säilyvät.',
    is: 'Fyrir hóp sem skiptist á tvær bókanir. Öll herbergi valdrar bókunar færast hingað; dagsetningar, herbergi, verð og gestir haldast.',
    sk: 'Pre skupinu rozdelenú do dvoch rezervácií. Všetky izby vybranej rezervácie prejdú do tejto; termíny, izby, ceny a hostia zostanú.',
    sl: 'Za skupino, razdeljeno na dve rezervaciji. Vse sobe izbrane rezervacije preidejo v to; datumi, sobe, cene in gostje ostanejo.',
    hu: 'Két foglalásra szakadt csoporthoz. A kiválasztott foglalás összes szobája ebbe kerül; a dátumok, szobák, árak és vendégek maradnak.',
    ro: 'Pentru un grup împărțit în două rezervări. Toate camerele rezervării alese trec în aceasta; datele, camerele, prețurile și oaspeții rămân.',
    bg: 'За група, разделена в две резервации. Всички стаи от избраната резервация преминават в тази; датите, стаите, цените и гостите остават.',
    hr: 'Za grupu podijeljenu u dvije rezervacije. Sve sobe odabrane rezervacije prelaze u ovu; datumi, sobe, cijene i gosti ostaju.',
    sr: 'Za grupu podeljenu u dve rezervacije. Sve sobe izabrane rezervacije prelaze u ovu; datumi, sobe, cene i gosti ostaju.',
    mk: 'За група поделена во две резервации. Сите соби од избраната резервација преминуваат во оваа; датумите, собите, цените и гостите остануваат.',
    sq: 'Për një grup të ndarë në dy rezervime. Të gjitha dhomat e rezervimit të zgjedhur kalojnë në këtë; datat, dhomat, çmimet dhe mysafirët mbeten.',
    el: 'Για ομάδα μοιρασμένη σε δύο κρατήσεις. Όλα τα δωμάτια της επιλεγμένης κράτησης μεταφέρονται σε αυτή· ημερομηνίες, δωμάτια, τιμές και επισκέπτες μένουν.',
    lt: 'Grupei, padalytai į dvi rezervacijas. Visi pasirinktos rezervacijos kambariai pereina į šią; datos, kambariai, kainos ir svečiai lieka.',
    lv: 'Grupai, kas sadalīta divās rezervācijās. Visi izvēlētās rezervācijas numuri pāriet uz šo; datumi, numuri, cenas un viesi paliek.',
    et: 'Kahte broneeringusse jagunenud grupile. Valitud broneeringu kõik toad liiguvad siia; kuupäevad, toad, hinnad ja külalised jäävad.' },
