  'checkin.alreadyInHouse': {
    de: 'Der Gast ist bereits eingecheckt, etwa vom Nachtlauf nach einer Anreise über den Schlüsselsafe. Meldeschein und AVS-Datei lassen sich hier nachholen.',
    en: 'The guest is already checked in, for example by the night audit after a late arrival via the key safe. The Meldeschein and the AVS file can be completed here.',
    tr: 'Misafir zaten check-in yapmış, örneğin anahtar kasası üzerinden geç varıştan sonra gece denetimi tarafından. Meldeschein ve AVS dosyası burada tamamlanabilir.',
    nl: 'De gast is al ingecheckt, bijvoorbeeld door de nachtaudit na een aankomst via de sleutelkluis. Meldeschein en AVS-bestand kunnen hier alsnog worden gemaakt.',
    da: 'Gæsten er allerede tjekket ind, f.eks. af night audit efter en ankomst via nøgleboksen. Meldeschein og AVS-fil kan færdiggøres her.',
    sv: 'Gästen är redan incheckad, t.ex. av nattrevisionen efter en ankomst via nyckelskåpet. Meldeschein och AVS-fil kan kompletteras här.',
    nb: 'Gjesten er allerede sjekket inn, for eksempel av nattrevisjonen etter en ankomst via nøkkelskapet. Meldeschein og AVS-fil kan tas igjen her.',
    pl: 'Gość jest już zameldowany, np. przez audyt nocny po przyjeździe przez sejf na klucze. Meldeschein i plik AVS można tu uzupełnić.',
    cs: 'Host už má provedený check-in, např. noční uzávěrkou po příjezdu přes trezor na klíče. Meldeschein a soubor AVS lze zde doplnit.',
    fr: 'Le client est déjà arrivé, par exemple via l’audit de nuit après une arrivée tardive par le coffre à clés. Le Meldeschein et le fichier AVS peuvent être complétés ici.',
    it: 'L’ospite ha già fatto il check-in, ad esempio dal night audit dopo un arrivo tramite cassetta delle chiavi. Meldeschein e file AVS si possono completare qui.',
    es: 'El huésped ya ha hecho el check-in, p. ej. por la auditoría nocturna tras una llegada con la caja de llaves. El Meldeschein y el archivo AVS se pueden completar aquí.',
    ru: 'Гость уже заселён, например ночным аудитом после позднего прибытия через ключевой сейф. Meldeschein и файл AVS можно оформить здесь.',
    uk: 'Гість уже зареєстрований, напр. нічним аудитом після заїзду через сейф для ключів. Meldeschein і файл AVS можна оформити тут.',
    zh: '宾客已办理入住，例如通过钥匙箱晚到后由夜审自动入住。可在此补办 Meldeschein 和 AVS 文件。',
    ko: '게스트가 이미 체크인되어 있습니다. 예를 들어 키 보관함을 통해 늦게 도착한 후 나이트 오딧에서 체크인된 경우입니다. Meldeschein과 AVS 파일은 여기서 보완할 수 있습니다.',
    ar: 'النزيل مسجّل وصوله بالفعل، مثلًا عبر التدقيق الليلي بعد وصول من خلال خزنة المفاتيح. يمكن استكمال Meldeschein وملف AVS هنا.',
    pt: 'O hóspede já fez check-in, por exemplo pelo fecho noturno após uma chegada através do cofre de chaves. O Meldeschein e o ficheiro AVS podem ser completados aqui.',
    fi: 'Vieras on jo kirjattu sisään, esimerkiksi yöajossa avainkaapin kautta tapahtuneen saapumisen jälkeen. Meldeschein ja AVS-tiedosto voidaan täydentää tässä.',
    is: 'Gesturinn er þegar innritaður, t.d. af næturuppgjörinu eftir síðkomu í gegnum lyklaboxið. Hér má ljúka Meldeschein og AVS-skránni.',
    sk: 'Hosť je už ubytovaný, napríklad nočnou uzávierkou po príchode cez trezor na kľúče. Meldeschein a súbor AVS sa tu dajú doplniť.',
    sl: 'Gost je že prijavljen, npr. z nočno zaključitvijo po prihodu prek sefa za ključe. Meldeschein in datoteko AVS lahko dokončate tukaj.',
    hu: 'A vendég már be van jelentkeztetve, például az éjszakai zárás által egy kulcsszéfen keresztüli érkezés után. A Meldeschein és az AVS-fájl itt pótolható.',
    ro: 'Oaspetele a făcut deja check-in, de exemplu prin night audit după o sosire târzie prin seiful pentru chei. Meldeschein și fișierul AVS pot fi completate aici.',
    bg: 'Гостът вече е настанен, напр. от нощния одит след пристигане чрез сейфа за ключове. Meldeschein и AVS файлът могат да се допълнят тук.',
    hr: 'Gost je već prijavljen, npr. noćnom obradom nakon dolaska preko sefa za ključeve. Meldeschein i AVS datoteka mogu se ovdje naknadno izraditi.',
    sr: 'Gost je već prijavljen, npr. noćnom revizijom posle kasnog dolaska preko sefa za ključeve. Meldeschein i AVS datoteka mogu se ovde naknadno uraditi.',
    mk: 'Гостинот веќе е пријавен, на пр. од ноќната ревизија по пристигнување преку сефот за клучеви. Meldeschein и AVS-датотеката може тука да се дополнат.',
    sq: 'Mysafiri ka bërë tashmë check-in, p.sh. nga auditi i natës pas një mbërritjeje përmes kasafortës së çelësave. Meldeschein dhe skedari AVS mund të plotësohen këtu.',
    el: 'Ο επισκέπτης έχει ήδη κάνει check-in, π.χ. από το νυχτερινό κλείσιμο μετά από άφιξη μέσω θυρίδας κλειδιών. Meldeschein και αρχείο AVS μπορούν να συμπληρωθούν εδώ εκ των υστέρων.',
    lt: 'Svečias jau užregistruotas, pvz., nakties audito po vėlyvo atvykimo per raktų seifą. Meldeschein ir AVS failą galima užbaigti čia.',
    lv: 'Viesis jau ir reģistrēts, piemēram, nakts auditā pēc ierašanās caur atslēgu seifu. Meldeschein un AVS failu var izveidot šeit.',
    et: 'Külaline on juba sisse registreeritud, nt ööauditi poolt pärast saabumist võtmeseifi kaudu. Meldescheini ja AVS-faili saab siin järele teha.' },
