  'checkin.signAtTerminal': {
    de: 'Die Unterschrift unter dem Meldeschein fehlt noch. Der Gast unterschreibt am Gästeterminal, dann geht der Check-in.',
    en: 'The registration form still needs the guest’s signature. The guest signs at the guest terminal; then check-in is possible.',
    tr: 'Meldeschein için misafirin imzası hâlâ eksik. Misafir terminalde imzalar, ardından check-in yapılabilir.',
    nl: 'De handtekening onder de Meldeschein ontbreekt nog. De gast ondertekent aan het gastenterminal, daarna kan worden ingecheckt.',
    da: 'Underskriften på registreringsblanketten mangler stadig. Gæsten skriver under ved gæsteterminalen, derefter kan check-in gennemføres.',
    sv: 'Registreringsblanketten saknar fortfarande gästens underskrift. Gästen skriver under vid gästterminalen, sedan kan incheckningen göras.',
    nb: 'Registreringsskjemaet mangler fortsatt signatur. Gjesten signerer på gjesteterminalen, deretter kan innsjekkingen gjøres.',
    pl: 'Brakuje jeszcze podpisu gościa na formularzu meldunkowym. Gość podpisuje na terminalu gościa, potem możliwe jest zameldowanie.',
    cs: 'Podpis pod Meldeschein ještě chybí. Host podepíše na terminálu pro hosty, pak lze provést check-in.',
    fr: 'La fiche d’enregistrement nécessite encore la signature du client. Le client signe au terminal client ; le check-in est ensuite possible.',
    it: 'Manca ancora la firma sulla scheda di registrazione. L’ospite firma al terminale ospiti, poi il check-in è possibile.',
    es: 'Falta aún la firma del parte de viajeros. El huésped firma en el terminal de huéspedes y entonces se puede hacer el check-in.',
    ru: 'Под регистрационной картой ещё нет подписи гостя. Гость подписывает на гостевом терминале, после этого возможно заселение.',
    uk: 'Під реєстраційною карткою ще бракує підпису. Гість підписує на терміналі для гостей, після цього можливий check-in.',
    zh: '住宿登记表尚缺签名。宾客在宾客终端上签名后，即可办理入住。',
    ko: '숙박 신고서에 아직 게스트 서명이 없습니다. 게스트가 게스트 단말기에서 서명하면 체크인할 수 있습니다.',
    ar: 'ما زال توقيع Meldeschein ناقصًا. يوقّع النزيل على شاشة النزلاء، ثم يمكن تسجيل الوصول.',
    pt: 'Falta ainda a assinatura do hóspede na ficha de registo. O hóspede assina no terminal de hóspedes; depois, o check-in é possível.',
    fi: 'Matkustajailmoituksesta puuttuu vielä vieraan allekirjoitus. Vieras allekirjoittaa vieraspäätteellä, minkä jälkeen sisäänkirjaus on mahdollinen.',
    is: 'Undirskrift gestsins vantar enn á skráningareyðublaðið. Gesturinn skrifar undir á gestaskjánum; þá er innritun möguleg.',
    sk: 'Pod registračným formulárom ešte chýba podpis. Hosť sa podpíše na termináli pre hostí, potom je check-in možný.',
    sl: 'Na prijavnici še manjka podpis gosta. Gost se podpiše na terminalu za goste, nato je prijava mogoča.',
    hu: 'A bejelentőlapról még hiányzik az aláírás. A vendég a vendégterminálon ír alá, utána lehet a check-in.',
    ro: 'Semnătura pe formularul de înregistrare lipsește încă. Oaspetele semnează la terminalul pentru oaspeți, apoi check-in-ul este posibil.',
    bg: 'Адресната карта още не е подписана. Гостът подписва на терминала за гости, след това е възможно настаняването.',
    hr: 'Na prijavnici još nedostaje potpis. Gost potpisuje na terminalu za goste, zatim je moguća prijava.',
    sr: 'Prijavnom listu još nedostaje potpis gosta. Gost potpisuje na terminalu za goste, zatim je check-in moguć.',
    mk: 'Потписот под Meldeschein сè уште недостасува. Гостинот потпишува на терминалот за гости, потоа е можен check-in.',
    sq: 'Formulari i regjistrimit ende pret nënshkrimin e mysafirit. Mysafiri nënshkruan në terminalin e mysafirëve, pastaj check-in është i mundur.',
    el: 'Λείπει ακόμη η υπογραφή στο Meldeschein. Ο επισκέπτης υπογράφει στο τερματικό επισκεπτών και μετά γίνεται το check-in.',
    lt: 'Registracijos kortelėje dar trūksta svečio parašo. Svečias pasirašo svečių terminale, tada galima registruoti atvykimą.',
    lv: 'Reģistrācijas veidlapai vēl trūkst viesa paraksta. Viesis parakstās viesu terminālī, tad reģistrācija ir iespējama.',
    et: 'Registreerimislehel puudub veel külalise allkiri. Külaline allkirjastab külalisterminalis, seejärel saab sisse registreerida.' },
