  'plan.channel.source': {
    de: 'Wird von einem Umsystem geführt ({channel}). Wer sie hier ändert, übernimmt sie in StayGrid; das Umsystem hält sie dann fest.',
    en: 'Managed by a connected system ({channel}). Changing it here takes it over in StayGrid; the connected system then keeps it fixed.',
    tr: 'Bağlı bir sistem tarafından yönetiliyor ({channel}). Burada değiştiren, rezervasyonu StayGrid\'e alır; bağlı sistem onu sabit tutar.',
    nl: 'Wordt beheerd door een gekoppeld systeem ({channel}). Wie haar hier wijzigt, neemt haar over in StayGrid; het gekoppelde systeem houdt haar dan vast.',
    da: 'Styres af et tilsluttet system ({channel}). Ændrer man den her, overtages den i StayGrid; det tilsluttede system holder den derefter fast.',
    sv: 'Hanteras av ett anslutet system ({channel}). Ändrar du den här tar StayGrid över den; det anslutna systemet låser den då.',
    nb: 'Styres av et tilknyttet system ({channel}). Endrer du den her, overtas den i StayGrid; det tilknyttede systemet holder den da fast.',
    pl: 'Zarządzana przez system zewnętrzny ({channel}). Zmiana tutaj przejmuje ją do StayGrid; system zewnętrzny pozostawia ją wtedy bez zmian.',
    cs: 'Spravováno připojeným systémem ({channel}). Kdo ji zde změní, převezme ji do StayGrid; připojený systém ji pak drží beze změny.',
    fr: 'Géré par un système connecté ({channel}). Le modifier ici le reprend dans StayGrid ; le système connecté le laisse alors inchangé.',
    it: 'Gestita da un sistema collegato ({channel}). Chi la modifica qui la acquisisce in StayGrid; il sistema collegato poi la lascia invariata.',
    es: 'Gestionada por un sistema conectado ({channel}). Quien la modifique aquí la asume en StayGrid; el sistema conectado la deja entonces fija.',
    ru: 'Ведётся подключённой системой ({channel}). Если изменить его здесь, оно переходит в StayGrid; подключённая система после этого его не меняет.',
    uk: 'Керується підключеною системою ({channel}). Змінивши його тут, Ви переносите керування в StayGrid; підключена система тоді більше його не змінює.',
    zh: '由外部系统管理（{channel}）。在此修改即由 StayGrid 接管；之后外部系统将不再更改它。',
    ko: '연동 시스템({channel})이 관리합니다. 여기서 변경하면 StayGrid로 넘어오며, 이후 연동 시스템은 이를 고정합니다.',
    ar: 'يديره نظام متصل ({channel}). من يغيّره هنا ينقله إلى StayGrid؛ ويثبّته النظام المتصل بعد ذلك.',
    pt: 'Gerida por um sistema externo ({channel}). Quem a alterar aqui assume-a no StayGrid; o sistema externo deixa então de a alterar.',
    fi: 'Liitetyn järjestelmän hallinnoima ({channel}). Muuttamalla sen tässä otat sen StayGridin hallintaan; liitetty järjestelmä pitää sen sen jälkeen ennallaan.',
    is: 'Stýrt af tengdu kerfi ({channel}). Ef henni er breytt hér tekur StayGrid hana yfir; tengda kerfið heldur henni þá fastri.',
    sk: 'Spravuje ju pripojený systém ({channel}). Kto ju tu zmení, prevezme ju do StayGrid; pripojený systém ju potom ponechá bez zmeny.',
    sl: 'Upravlja jo povezan sistem ({channel}). Kdor jo tu spremeni, jo prevzame v StayGrid; povezani sistem jo nato pusti pri miru.',
    hu: 'Egy kapcsolt rendszer kezeli ({channel}). Aki itt módosítja, átveszi a StayGridbe; a kapcsolt rendszer ezután nem változtat rajta.',
    ro: 'Gestionată de un sistem conectat ({channel}). Cine o modifică aici o preia în StayGrid; sistemul conectat o lasă apoi neschimbată.',
    bg: 'Управлява се от свързана система ({channel}). Ако я промените тук, тя се поема в StayGrid; свързаната система след това я оставя непроменена.',
    hr: 'Vodi je povezani sustav ({channel}). Tko je ovdje promijeni, preuzima je u StayGrid; povezani sustav je tada više ne mijenja.',
    sr: 'Vodi je povezani sistem ({channel}). Ko je ovde izmeni, preuzima je u StayGrid; povezani sistem je tada više ne menja.',
    mk: 'Се води од поврзан систем ({channel}). Ако ја промените тука, ја преземате во StayGrid; поврзаниот систем потоа ја остава непроменета.',
    sq: 'Menaxhohet nga një sistem i lidhur ({channel}). Kush e ndryshon këtu, e merr në StayGrid; sistemi i lidhur pastaj e mban të fiksuar.',
    el: 'Διαχειρίζεται από εξωτερικό σύστημα ({channel}). Όποιος την αλλάξει εδώ, την αναλαμβάνει στο StayGrid· το εξωτερικό σύστημα τότε την κρατά σταθερή.',
    lt: 'Valdoma susietos sistemos ({channel}). Pakeitus čia, valdymą perima StayGrid; susieta sistema tada jos nebekeičia.',
    lv: 'To pārvalda pievienota sistēma ({channel}). Kas to maina šeit, pārņem to StayGrid; pievienotā sistēma tad to atstāj nemainītu.',
    et: 'Haldab ühendatud süsteem ({channel}). Siin muutmine võtab selle StayGridi üle; ühendatud süsteem hoiab selle siis fikseerituna.' },
